function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // painting goes here
  brush.fill("#7f0b00", 100); // sky blue
  brush.circle(200, 200, 100); // sun

  brush.fill("#003300", 50); // green hills
  brush.vertex(200, 200); // top of hill
  brush.vertex(100, 300); // left side of hill
  brush.vertex(150, 300); // right side of hill
  brush.vertex(250, 300); // bottom of hill
  brush.endShape(true);

  brush.fill("#000000", 200); // green ground
  brush.vertex(200, 250); // top of ground
  brush.vertex(100, 350); // left side of ground
  brush.vertex(150, 350); // right side of ground
  brush.vertex(250, 350); // bottom of ground
  brush.endShape(true);

  brush.fill("#002200", 70); // green details
  brush.vertex(175, 325); // top of detail
  brush.vertex(125, 375); // left side of detail
  brush.vertex(175, 375); // right side of detail
  brush.vertex(125, 325); // bottom of detail
  brush.endShape(true);
}

