  brush.fill("#000000", 0.7); // Medium green
  brush.beginShape();
  brush.vertex(170, 170);
  brush.vertex(230, 170);
  brush.vertex(190, 230); // Smoother hills
  brush.endShape(true);

  // Tree on the hill
  brush.fill("#000000", 0.5); // Dark green
  brush.beginShape();
  brush.vertex(180, 190); // Tree
  brush.endShape(true);

  // Add a flower
  brush.fill("#000000", 0.4); // Dark green
  brush.beginShape();
  brush.vertex(200, 200); // Flower
  brush.endShape(true);
}

